<section class="panel profile-panel"><div class="profile-heading"><div class="profile-photo"><?php if ($user['profile_picture']): ?><img src="media.php" alt="Your profile picture"><?php else: ?><span><?= e(mb_substr($user['first_name'], 0, 1)) ?></span><?php endif; ?></div><div><h2><?= e($user['first_name'].' '.$user['last_name']) ?></h2><p class="muted"><?= e($user['email']) ?></p></div></div>
<form action="action.php" method="post" enctype="multipart/form-data" class="form-stack" novalidate>
    <?= csrf_field() ?><input type="hidden" name="action" value="save_profile">
    <div class="profile-field"><button class="field-edit" type="button" data-edit="full-name">Full Name <span>Edit ↗</span></button><fieldset id="full-name" class="edit-group"><legend class="sr-only">Full Name</legend><div class="form-grid"><label>First Name<input name="first_name" maxlength="75" autocomplete="given-name" value="<?= form_value('profile', 'first_name', $user['first_name']) ?>" readonly required></label><label>Last Name<input name="last_name" maxlength="75" autocomplete="family-name" value="<?= form_value('profile', 'last_name', $user['last_name']) ?>" readonly required></label></div></fieldset></div>
    <div class="profile-field"><button class="field-edit" type="button" data-edit="profile-email">Email Address <span>Edit ↗</span></button><input aria-label="Email Address" id="profile-email" name="email" type="email" maxlength="255" value="<?= form_value('profile', 'email', $user['email']) ?>" readonly required></div>
    <div class="profile-field"><button class="field-edit" type="button" data-edit="profile-phone">Phone Number <span>Edit ↗</span></button><input aria-label="Contact Number" id="profile-phone" name="contact_number" type="tel" maxlength="30" value="<?= form_value('profile', 'contact_number', $user['contact_number']) ?>" readonly required></div>
    <label class="file-label">Upload Profile Picture<input type="file" name="profile_picture" accept=".jpg,.jpeg,.png"><small>JPG or PNG, up to 2 MB. Leave empty to keep your picture.</small></label>
    <div class="button-row"><button class="button primary" type="submit">Save</button></div>
</form></section>
